def find_help_override(args):
    # Find earliest of --help, -h, --version, --errorlist, --doc (exact matches)
    # Returns (index, type) or (None, None)
    earliest_idx = None
    earliest_type = None
    for idx, arg in enumerate(args):
        if idx == 0:
            continue
        if arg in ("--help", "-h"):
            typ = "help"
        elif arg == "--version":
            typ = "version"
        elif arg == "--errorlist":
            typ = "errorlist"
        elif arg == "--doc":
            typ = "doc"
        else:
            continue
        if earliest_idx is None or idx < earliest_idx:
            earliest_idx = idx
