def is_vs_project(project_path):
    if project_path is None:
        return False
    return project_path.endswith(".sln") or project_path.endswith(".vcxproj")

def handle_deferred_checks(res):
    s = res.settings
    # Project-configuration check: if specified and no VS project, error at its pos
    # This error should be considered among immediate errors for ordering (earliest wins)
    # So we add it to errors list now (with its pos), then later we will sort and report earliest.
    if res.project_config_pos is not None:
        if not is_vs_project(s.project):
