    # Note: platform and library are handled separately after immediate, not in same ordering.
    # So return immediate errors sorted? Actually immediate errors already in order of appearance (since we appended in order). But project-config may be out of order (since added at end). So sort by pos.
    # For other immediate errors, they are already in pos order because we parsed sequentially. But to be safe, sort.
    if res.errors:
        res.errors.sort(key=lambda x: x[0])
        # Report earliest
        return res.errors[0][1]
    return None

def check_platform_deferred(res):
