    try:
        exe = sys.argv[0]
        # If exe contains dir separator, use its dir; else search PATH? For ./executable, exe is ./executable, dir is .
        # Use realpath to resolve symlinks?
        if os.path.dirname(exe) == "":
            # No dir, search PATH? For now, use cwd?
            return os.getcwd()
        else:
