def find_library_file(lib_name):
    # lib_name is single library string (without comma, non-empty)
    # Returns filepath if found, else None
    # Logic:
    # If lib_name contains "/": treat as path (absolute or relative to cwd). Try directly.
    # Else: try cwd/<file>, exedir/<file>, exedir/cfg/<file>, FILESDIR/cfg/<file>
    # Where <file> is lib_name if endswith .cfg else lib_name + .cfg
    # Note: for std, lib_name is "std.cfg" or "std"? Actually std is always "std.cfg" display, but search similarly.
    # For generic, determine filename:
    if "/" in lib_name:
        # Path
        # If absolute, use as is; if relative, resolve relative to cwd
        if os.path.isabs(lib_name):
            cand = lib_name
        else:
            cand = os.path.join(os.getcwd(), lib_name)
        # Normalize? For ./my.cfg, join gives /cwd/./my.cfg, isfile should handle.
        if os.path.isfile(cand):
            return cand
        else:
            return None
    else:
        # No slash
        if lib_name.endswith(".cfg"):
            fname = lib_name
        else:
            fname = lib_name + ".cfg"
        # Try cwd
        cwd_cand = os.path.join(os.getcwd(), fname)
        if os.path.isfile(cwd_cand):
            return cwd_cand
        # Try exedir
        exedir = get_exe_dir()
        exedir_cand = os.path.join(exedir, fname)
        if os.path.isfile(exedir_cand):
            return exedir_cand
        exedir_cfg_cand = os.path.join(exedir, "cfg", fname)
        if os.path.isfile(exedir_cfg_cand):
            return exedir_cfg_cand
        # Try FILESDIR/cfg
        filesdir_cand = os.path.join(FILESDIR, "cfg", fname)
        if os.path.isfile(filesdir_cand):
            return filesdir_cand
        return None

